import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BWuWLRhz.js";const x=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/legacy/React系列/采用NextJs实现react的服务端渲染（附源码）.md","filePath":"wiki/legacy/React系列/采用NextJs实现react的服务端渲染（附源码）.md"}'),n={name:"wiki/legacy/React系列/采用NextJs实现react的服务端渲染（附源码）.md"};function p(c,e,i,o,l,h){return t(),s("div",null,[...e[0]||(e[0]=[r(`<p>最近心血来潮，想尝试一下react的服务端渲染，说一下我一开始的思路到最后的实现。</p><h3 id="思路分析" tabindex="-1">思路分析 <a class="header-anchor" href="#思路分析" aria-label="Permalink to &quot;思路分析&quot;">​</a></h3><p>刚开始没有具体的思路，看了react官网的服务端渲染API，看了react-router4官网的服务端渲染DEMO，接着在网上搜索了一些别人写的博客，这方面博客挺少，而且介绍不全面。</p><p>我的想法是在现有客户端源码的基础上（<a href="https://github.com/hyy1115/react-redux-webpack3%EF%BC%89%EF%BC%8C%E5%8A%A0%E4%B8%8A%E6%9C%8D%E5%8A%A1%E7%AB%AF%E6%B8%B2%E6%9F%93%E7%9A%84%E4%BB%A3%E7%A0%81%E3%80%82" target="_blank" rel="noreferrer">https://github.com/hyy1115/react-redux-webpack3），加上服务端渲染的代码。</a></p><p>恩，这看起来似乎很简单，接着我就开始研究，我先是构建了一个server.js和client.js来区分不同的环境，并且在server.js中调用了react/server的API渲染了一个静态页面，这一步很正常，没有任何问题。</p><p>接着，在我以为很快就能实现的时候，我把渲染的入口改成了react-router4推荐的静态路由模式，啪啪啪，超多的error扑面而来，染红了terminal。我想了想，伤心了一下。</p><p>都是些什么错误呢？</p><p>1、css报错，不管是less、css、scss，始终无法解析，原因在于服务端不支持解析。</p><p>2、图片报错，图片也无法解析。</p><p>3、window对象下的变量报错，服务端是global环境。</p><p>4、js的各种报错。</p><p>5、路径报错。</p><p>7、未知的报错。</p><p>一整天我都在修复这些bug，最后太多太多，让我心累，就去咨询了一个大佬，大佬告诉我，使用nextjs，真是一语惊醒梦中人，我还自己配置这些环境太傻了吧。</p><h3 id="nextjs框架" tabindex="-1">NextJS框架 <a class="header-anchor" href="#nextjs框架" aria-label="Permalink to &quot;NextJS框架&quot;">​</a></h3><p>Next地址：<a href="https://github.com/zeit/next.js" target="_blank" rel="noreferrer">https://github.com/zeit/next.js</a></p><h4 id="next是什么" tabindex="-1">next是什么 <a class="header-anchor" href="#next是什么" aria-label="Permalink to &quot;next是什么&quot;">​</a></h4><p>react服务端渲染框架</p><h4 id="next简介" tabindex="-1">next简介 <a class="header-anchor" href="#next简介" aria-label="Permalink to &quot;next简介&quot;">​</a></h4><p>推荐你点击上面的网址看看readme的介绍，非常详细。</p><h2 id="react-next服务端渲染项目搭建" tabindex="-1">react-next服务端渲染项目搭建 <a class="header-anchor" href="#react-next服务端渲染项目搭建" aria-label="Permalink to &quot;react-next服务端渲染项目搭建&quot;">​</a></h2><p><strong>项目地址：<a href="https://github.com/hyy1115/react-next" target="_blank" rel="noreferrer">https://github.com/hyy1115/react-next</a></strong></p><h4 id="实现的功能" tabindex="-1">实现的功能 <a class="header-anchor" href="#实现的功能" aria-label="Permalink to &quot;实现的功能&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1、服务端渲染，支持react16</span></span>
<span class="line"><span>2、webpack，包括开发环境下的热更新等功能，以及部署环境下的打包功能</span></span>
<span class="line"><span>3、babelrc配置</span></span>
<span class="line"><span>4、支持scss、css、css-jsx</span></span>
<span class="line"><span>5、支持next-router</span></span>
<span class="line"><span>6、支持redux</span></span>
<span class="line"><span>7、支持图片格式文件</span></span>
<span class="line"><span>8、支持axios</span></span></code></pre></div><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>使用next框架，你仍旧可以采用客户端react组件的写法，只是在redux和router的选择上，使用next集成的redux和router功能，项目结构上面，和客户端渲染的写法有些许不同。</p><p><strong>详细教程晚些时候会在项目中更新。</strong></p><p><img src="https://gitee.com/birdassassin/frontend-wiki/raw/master/img/bVWJ5y" alt="图片描述"></p>`,28)])])}const u=a(n,[["render",p]]);export{x as __pageData,u as default};
